"""`main` regenerates `analytics.ihpo` with every analytics field filled.
`test2.ihpo` predates the sensitivity, mistunability and interaction fields, and
nineteen tests pin its trials. The run takes five seconds, so `analytics.ihpo`
is committed and regenerated by hand after result-format changes.
"""

from importlib.metadata import version as dist_version
from pathlib import Path

from core import datasets, io, provenance
from core.metrics import METRICS
from core.models import RandomForestModel
from core.optimizers import RandomOptimizer

HERE = Path(__file__).resolve().parent
DATASET = HERE.parent.parent / "datasets" / "iris.csv"
OUT = HERE / "analytics.ihpo"

METRIC_NAMES = ("accuracy", "f1")
N_TRIALS = 6
SEED = 0


def main() -> None:
    X_train, X_val, y_train, y_val = datasets.load_splits(DATASET, SEED)
    metrics = {name: METRICS[name] for name in METRIC_NAMES}
    optimizer = RandomOptimizer()
    result = optimizer.optimize(
        RandomForestModel(), X_train, y_train, X_val, y_val,
        metrics=metrics, primary_metric="accuracy", n_trials=N_TRIALS, seed=SEED,
    )

    for field in ("hyperparameter_importance", "hyperparameter_sensitivity",
                  "hyperparameter_mistunability", "hyperparameter_interactions"):
        for name in METRIC_NAMES:
            assert getattr(result, field).get(name), f"{field}/{name} came out empty"

    OUT.write_bytes(io.to_bytes({
        "format": io.SNAPSHOT_FORMAT,
        "version": dist_version("codesigner"),
        "name": "analytics",
        "seed": SEED,
        "dataset": {"filename": DATASET.name, "path": str(DATASET)},
        "model": {"kind": "registry", "name": RandomForestModel().name, "path": ""},
        "evaluation": provenance.evaluation(0),
        "metrics": {"names": list(metrics), "current": "accuracy", "original": "accuracy"},
        "optimizer": {"name": optimizer.name, "params": optimizer.get_params()},
        "result": optimizer.serialize_result(result),
    }))
    print(f"wrote {OUT} ({OUT.stat().st_size:,} bytes, {len(result.trials)} trials)")


if __name__ == "__main__":
    main()
